const tabId = 1148881640;
const topListings = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/homedetails/"]'));
  const results = [];
  const seen = new Set();

  for (const a of links) {
    if (seen.has(a.href)) continue;
    seen.add(a.href);

    // Get the card container
    let parent = a;
    while (parent && !parent.innerText.includes('$') && parent !== document.body) {
      parent = parent.parentElement;
    }
    // go up to card boundary
    while (parent && parent.parentElement && !parent.parentElement.innerText.startsWith('140 Homes') && parent.parentElement !== document.body && parent.parentElement.querySelectorAll('a[href*="/homedetails/"]').length <= 1) {
      parent = parent.parentElement;
    }

    results.push({
      href: a.href,
      addressText: a.innerText.trim(),
      cardText: parent ? parent.innerText.trim() : ""
    });
  }
  return results;
});

console.log(`Extracted ${topListings.length} homedetails listings.`);
