const tabId = 1148881640;
const listings = await browserjs(tabId, () => {
  // Let's find all listing cards
  // Compass listing cards usually have links to /listing/...
  const links = Array.from(document.querySelectorAll('a[href*="/listing/"]'));
  const cards = [];
  const seenUrls = new Set();

  for (const a of links) {
    const url = a.href;
    if (seenUrls.has(url)) continue;
    seenUrls.add(url);

    // Find container card
    let container = a.closest('[data-tn*="listing-card"]') || a.closest('article') || a.parentElement;
    while (container && container !== document.body && !container.innerText.includes('$')) {
      container = container.parentElement;
    }
    // Go up a bit more to get full card text
    let cardEl = container;
    for (let i = 0; i < 3; i++) {
      if (cardEl && cardEl.parentElement && cardEl.parentElement.innerText.length < (cardEl.innerText.length + 200)) {
        cardEl = cardEl.parentElement;
      }
    }

    cards.push({
      url,
      linkText: a.innerText.trim(),
      cardText: cardEl ? cardEl.innerText : ""
    });
  }

  return cards;
});

console.log(`Found ${listings.length} listings:`);
listings.slice(0, 10).forEach((l, idx) => {
  console.log(`--- Listing ${idx + 1} ---`);
  console.log("URL:", l.url);
  console.log("Link text:", l.linkText);
  console.log("Card text:\n", l.cardText.slice(0, 300));
});

