await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

const allTopListings = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/homedetails/"]'));
  const results = [];
  const seen = new Set();

  for (const a of links) {
    if (seen.has(a.href)) continue;
    seen.add(a.href);

    let parent = a;
    for (let i = 0; i < 5; i++) {
      if (parent && parent.parentElement && !parent.parentElement.innerText.startsWith('140 Homes') && parent.parentElement.querySelectorAll('a[href*="/homedetails/"]').length <= 1) {
        parent = parent.parentElement;
      }
    }

    const priceMatch = parent?.innerText.match(/\$[\d,]+/);
    const bedsMatch = parent?.innerText.match(/(\d+)\s*(?:beds|Bedrooms)/i);
    const bathsMatch = parent?.innerText.match(/(\d+(?:\.\d+)?)\s*(?:baths|Bathrooms)/i);

    results.push({
      url: a.href,
      text: a.innerText.trim().replace(/\n+/g, ', '),
      price: priceMatch ? priceMatch[0] : null,
      beds: bedsMatch ? bedsMatch[1] : null,
      baths: bathsMatch ? bathsMatch[1] : null,
      cardText: parent?.innerText.trim().slice(0, 200).replace(/\n+/g, ' ')
    });
  }
  return results;
});

console.log("Top 10 listings from search:");
allTopListings.slice(0, 10).forEach((l, i) => {
  console.log(`${i+1}. ${l.price} | ${l.text} | ${l.beds} beds, ${l.baths} baths | ${l.url}`);
});

